def load() -> pd.DataFrame:
    return pd.read_csv(
        'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Identity_Theft_Reports.csv',
        skiprows=2
    )

def process(identity_theft) -> pd.DataFrame:
    df = identity_theft.dropna(subset=['State'])
    alabama = df[df['State'] == 'Alabama'].copy()
    alabama['reports_int'] = alabama['# of Reports'].str.replace(',', '').astype(int)
    total = alabama['reports_int'].sum()
    return pd.DataFrame({'Total Reports': [total]})
